local FortuneTeller = {}
local PRODUCTS = {
    palm_reading = { name = "Branje dlani", inkCost = 1, parchmentCost = 1, time = 2, cost = 25, accuracy = 40, happiness = 2, description = "Branje dlani za napovedovanje prihodnosti." },
    tarot_reading = { name = "Tarot branje", tarotCardCost = 1, parchmentCost = 1, time = 4, cost = 60, accuracy = 55, prestige = 3, happiness = 3, description = "Tarot branje za napovedovanje usode." },
    crystal_gazing = { name = "Kristalogledje", crystalCost = 1, silverCost = 1, time = 6, cost = 140, accuracy = 70, prestige = 6, happiness = 4, description = "Kristalogledje za vizije prihodnosti." },
    silver_bowl_scrying = { name = "Srebrnokotansko gledanje", crystalCost = 1, silverCost = 1, goldCost = 1, time = 9, cost = 320, accuracy = 82, prestige = 12, happiness = 5, description = "Gledanje v srebrni kotan za plemiče." },
    gold_astrolabe_divination = { name = "Zlatoastrološko vedeževanje", crystalCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, time = 12, cost = 680, accuracy = 92, prestige = 20, happiness = 7, description = "Vedeževanje z zlatim astrolabom za visoke plemiče." },
    royal_grand_prophecy = { name = "Kraljevski veliki prerokba", crystalCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 17, cost = 1800, accuracy = 100, prestige = 42, happiness = 12, description = "Velika kraljevska prerokba z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Vedeževalska postaja", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    divination_room = { name = "Vedeževalnica", cost = { gold = 950, wood = 250, stone = 450, crystal = 8 }, upkeep = 23, qualityBonus = 18 },
    scrying_chamber = { name = "Gledalna komora", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, ink = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_divination_atelier = { name = "Kraljevski atelje vedeževanja", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
FortuneTeller.inkStock = 12; FortuneTeller.parchmentStock = 14; FortuneTeller.tarotCardStock = 10; FortuneTeller.crystalStock = 10; FortuneTeller.silverStock = 8; FortuneTeller.goldStock = 6; FortuneTeller.jewelStock = 6; FortuneTeller.pearlStock = 4
FortuneTeller.productStock = {}; FortuneTeller.buildings = {}; FortuneTeller.maker = nil; FortuneTeller.activeMaking = {}; FortuneTeller.totalProducts = 0; FortuneTeller.dayTimer = 0
function FortuneTeller.init() FortuneTeller.inkStock=12; FortuneTeller.parchmentStock=14; FortuneTeller.tarotCardStock=10; FortuneTeller.crystalStock=10; FortuneTeller.silverStock=8; FortuneTeller.goldStock=6; FortuneTeller.jewelStock=6; FortuneTeller.pearlStock=4; FortuneTeller.productStock={}; FortuneTeller.buildings={}; FortuneTeller.maker=nil; FortuneTeller.activeMaking={}; FortuneTeller.totalProducts=0; FortuneTeller.dayTimer=0; print("[FortuneTeller] Royal Fortune Teller System initialized (6 products, 4 buildings)") end
function FortuneTeller.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FortuneTeller.maker={name=n or ("Vedeževalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vedeževalec najet: %s (spretnost: %d)",FortuneTeller.maker.name,s),"success") end; return true end
function FortuneTeller.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FortuneTeller.build(id) local ok,e=FortuneTeller.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FortuneTeller.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FortuneTeller.getQualityBonus() local b=0; for _,bd in ipairs(FortuneTeller.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FortuneTeller.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.inkCost and FortuneTeller.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.parchmentCost and FortuneTeller.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.tarotCardCost and FortuneTeller.tarotCardStock<(d.tarotCardCost or 0) then return false,"Premalo tarot kart" end; if d.crystalCost and FortuneTeller.crystalStock<(d.crystalCost or 0) then return false,"Premalo kristalov" end; if d.silverCost and FortuneTeller.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FortuneTeller.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FortuneTeller.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FortuneTeller.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FortuneTeller.buildings==0 then return false,"Potrebna delavnica" end; if not FortuneTeller.maker then return false,"Potreben vedeževalec" end; return true end
function FortuneTeller.make(pt,qty) qty=qty or 1; local ok,e=FortuneTeller.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.inkCost then FortuneTeller.inkStock=FortuneTeller.inkStock-d.inkCost*qty end; if d.parchmentCost then FortuneTeller.parchmentStock=FortuneTeller.parchmentStock-d.parchmentCost*qty end; if d.tarotCardCost then FortuneTeller.tarotCardStock=FortuneTeller.tarotCardStock-d.tarotCardCost*qty end; if d.crystalCost then FortuneTeller.crystalStock=FortuneTeller.crystalStock-d.crystalCost*qty end; if d.silverCost then FortuneTeller.silverStock=FortuneTeller.silverStock-d.silverCost*qty end; if d.goldCost then FortuneTeller.goldStock=FortuneTeller.goldStock-d.goldCost*qty end; if d.jewelCost then FortuneTeller.jewelStock=FortuneTeller.jewelStock-d.jewelCost*qty end; if d.pearlCost then FortuneTeller.pearlStock=FortuneTeller.pearlStock-d.pearlCost*qty end; local t=d.time; if FortuneTeller.maker then t=math.max(1,t-math.floor(FortuneTeller.maker.skill/12)) end; table.insert(FortuneTeller.activeMaking,{id="fortune_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FortuneTeller.completeMaking(m) local q=1.0+(FortuneTeller.getQualityBonus()/100); if FortuneTeller.maker then q=q+(FortuneTeller.maker.skill/180) end; q=math.min(2.0,q); FortuneTeller.productStock[m.productType]=(FortuneTeller.productStock[m.productType] or 0)+m.quantity; FortuneTeller.totalProducts=FortuneTeller.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FortuneTeller.maker then FortuneTeller.maker.itemsMade=FortuneTeller.maker.itemsMade+m.quantity; if math.random()<0.20 then FortuneTeller.maker.skill=math.min(100,FortuneTeller.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vedeževanje opravljeno: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fortune.completed",{productName=m.productName,accuracy=m.accuracy,prestige=m.prestige,happiness=m.happiness}) end end
function FortuneTeller.update(dt) if not _G.state then return end; FortuneTeller.dayTimer=FortuneTeller.dayTimer+dt; if FortuneTeller.dayTimer>=30 then FortuneTeller.dayTimer=0; for i=#FortuneTeller.activeMaking,1,-1 do local m=FortuneTeller.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FortuneTeller.completeMaking(m); table.remove(FortuneTeller.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FortuneTeller.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FortuneTeller.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FortuneTeller.getStats() return {inkStock=FortuneTeller.inkStock,parchmentStock=FortuneTeller.parchmentStock,tarotCardStock=FortuneTeller.tarotCardStock,crystalStock=FortuneTeller.crystalStock,silverStock=FortuneTeller.silverStock,goldStock=FortuneTeller.goldStock,jewelStock=FortuneTeller.jewelStock,pearlStock=FortuneTeller.pearlStock,productStock=FortuneTeller.productStock,numBuildings=#FortuneTeller.buildings,hasMaker=FortuneTeller.maker~=nil,makerName=FortuneTeller.maker and FortuneTeller.maker.name or "—",makerSkill=FortuneTeller.maker and FortuneTeller.maker.skill or 0,activeMaking=#FortuneTeller.activeMaking,totalProducts=FortuneTeller.totalProducts} end
return FortuneTeller
